import type { MetadataRoute } from "next";

/** Installable admin PWA. Opens straight to the calendar; icons are generated by scripts/generate-pwa-icons.mjs. */
export default function manifest(): MetadataRoute.Manifest {
  return {
    id: "/calendar",
    name: "Ryan Kennedy Hairdressing Admin",
    short_name: "RK Admin",
    description: "Run the diary, bookings and clients for Ryan Kennedy Hairdressing.",
    start_url: "/calendar",
    scope: "/",
    display: "standalone",
    orientation: "portrait",
    background_color: "#fff8f1",
    theme_color: "#fff8f1",
    categories: ["business", "productivity"],
    icons: [
      { src: "/icons/icon-192.png", sizes: "192x192", type: "image/png", purpose: "any" },
      { src: "/icons/icon-512.png", sizes: "512x512", type: "image/png", purpose: "any" },
      {
        src: "/icons/icon-maskable-512.png",
        sizes: "512x512",
        type: "image/png",
        purpose: "maskable",
      },
    ],
    shortcuts: [
      { name: "Calendar", url: "/calendar" },
      { name: "Bookings", url: "/bookings" },
      { name: "Clients", url: "/clients" },
    ],
  };
}
